/* ---------- batch five ---------- */
.ch{padding:0}
.ch-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:14px 16px 10px}
.ch-val{display:flex;align-items:center;gap:10px;margin-top:4px;font-family:var(--mono);font-weight:700;font-size:26px;letter-spacing:-.5px}
.ch-legend{display:flex;gap:16px;padding:10px 16px 14px;font-size:12px;color:var(--text-dim)}
.ch-legend span{display:inline-flex;align-items:center;gap:6px}
.sw.dash{background:repeating-linear-gradient(90deg,var(--muted) 0 3px,transparent 3px 5px);height:2px;width:12px}
.ch-tip{position:absolute;top:6px;padding:6px 8px;background:var(--panel);border:1px solid var(--icon-line);font-size:12px;white-space:nowrap;opacity:0;transition:opacity .2s;pointer-events:none;z-index:2}
.ch-tip .mono-xs{display:block;font-size:10px}
.ch-tip b{font-family:var(--mono)}

/* donut */
.dn-body{display:grid;grid-template-columns:150px 1fr;gap:16px;align-items:center;padding:6px 16px 16px}
.dn-ring{position:relative;width:150px;height:150px}
.dn-ring svg{width:100%;height:100%;transform:rotate(-90deg)}
.dn-track{fill:none;stroke:var(--line);stroke-width:14}
.dn-seg{fill:none;stroke-width:14;transition:stroke-dasharray .9s var(--ease),opacity .25s,stroke-width .3s var(--ease);cursor:pointer}
.dn-svg-hov .dn-seg:not(.on){opacity:.3}
.dn-seg.on{stroke-width:17}
.dn-center{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;pointer-events:none}
.dn-ring .ch-tip{top:0;left:0}
.dn-row{cursor:pointer}
.dn-row.pinned{color:var(--text);background:var(--accent-bg);box-shadow:inset 2px 0 0 var(--accent)}
.dn-row.pinned .v{color:var(--accent)}
.dn-v{font-family:var(--mono);font-weight:700;font-size:22px}
.dn-legend{display:flex;flex-direction:column}
.dn-row{display:flex;align-items:center;gap:10px;padding:8px;font-size:13px;color:var(--text-dim);transition:color .25s,background-color .25s;cursor:default}
.dn-row.on{color:var(--text);background:rgba(var(--fg-rgb),.03)}
.dn-row .v{margin-left:auto}

/* ---------- donut chart ---------- */
{
  const svg = $('#dn-svg'), legend = $('#dn-legend'), R = 46, C = 2 * Math.PI * R, GAP = 2.5;
  const data = [['Organic', 42, 'var(--accent)'], ['Referral', 24, 'rgba(255,133,13,.55)'], ['Social', 18, 'rgba(var(--fg-rgb),.45)'], ['Direct', 16, 'rgba(var(--fg-rgb),.2)']];
  let off = 0;
  const segs = data.map(([n, v, col], i) => {
    const c = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
    c.setAttribute('cx', 60); c.setAttribute('cy', 60); c.setAttribute('r', R); c.setAttribute('class', 'dn-seg'); c.style.stroke = col;
    c.dataset.len = Math.max(0, v / 100 * C - GAP); c.style.strokeDasharray = `0 ${C}`; c.style.strokeDashoffset = -off; off += v / 100 * C;
    c.dataset.i = i; svg.appendChild(c); return c;
  });
  legend.innerHTML = data.map(([n, v, col], i) => `<div class="dn-row" data-i="${i}" role="button" tabindex="0"><i class="sw" style="background:${col}"></i>${n}<span class="mono-xs v">${v}%</span></div>`).join('');
  const rows = $$('.dn-row', legend), ring = $('#dn-ring'), tip = $('#dn-tip');
  let pinned = null;
  // show one segment: dim the rest, highlight its row, update the centre
  function show(i){
    svg.classList.toggle('dn-svg-hov', i != null);
    segs.forEach((s, n) => s.classList.toggle('on', n === i)); rows.forEach((r, n) => r.classList.toggle('on', n === i));
    swapText($('#dn-v'), i == null ? '100%' : data[i][1] + '%'); swapText($('#dn-l'), i == null ? 'All sources' : data[i][0]);
  }
  function pin(i){
    pinned = pinned === i ? null : i;
    rows.forEach((r, n) => r.classList.toggle('pinned', n === pinned));
    show(pinned); Sound.play(pinned == null ? 'tick' : 'select');
  }
  segs.forEach(s => {
    s.addEventListener('mouseenter', () => { show(+s.dataset.i); Sound.play('stream'); });
    s.addEventListener('mousemove', e => {
      const i = +s.dataset.i, r = ring.getBoundingClientRect();
      tip.innerHTML = `<span class="mono-xs">${data[i][0]}</span><b>${data[i][1]}%</b> of traffic`;
      tip.style.transform = `translate(${Math.min(r.width - 20, e.clientX - r.left + 12)}px, ${e.clientY - r.top + 12}px)`; tip.style.opacity = '1';
    });
    s.addEventListener('mouseleave', () => { tip.style.opacity = '0'; show(pinned); });
    s.addEventListener('click', () => pin(+s.dataset.i));
  });
  rows.forEach(r => {
    r.addEventListener('mouseenter', () => { show(+r.dataset.i); Sound.play('stream'); });
    r.addEventListener('mouseleave', () => show(pinned));
    r.addEventListener('click', () => pin(+r.dataset.i));
    r.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' '){ e.preventDefault(); pin(+r.dataset.i); } });
  });
  whenSeen($('#c43'), () => segs.forEach((s, i) => setTimeout(() => { s.style.strokeDasharray = `${s.dataset.len} ${C}`; ambient('c43', 'tick'); }, i * 160)));
}
